n = int(input())
res = []
for i in range(2, n + 1):
    is_p = True
    for j in range(2, int(i ** 0.5) + 1):
        if i % j == 0:
            is_p = False
            break
    if is_p:
        res.append(i)
print(' '.join(map(str, res)))

