n = int(input())
a = list(map(int, input().split()))
avg = round(sum(a) / n)
if avg >= 90:
    g = "A"
elif avg >= 80:
    g = "B"
elif avg >= 70:
    g = "C"
elif avg >= 60:
    g = "D"
else:
    g = "F"
print(avg, g)

