parts = input().split()
a, op, b = int(parts[0]), parts[1], int(parts[2])
if op == '+':
    print(a + b)
elif op == '-':
    print(a - b)
elif op == '*':
    print(a * b)
elif op == '/':
    if b == 0:
        print("除數不可為0")
    else:
        print(f"{a / b:.2f}")

