x, y = map(int, input().split())
if x == 0 and y == 0:
    print("原點")
elif x == 0:
    print("y軸上")
elif y == 0:
    print("x軸上")
elif x > 0 and y > 0:
    print("象限一")
elif x < 0 and y > 0:
    print("象限二")
elif x < 0 and y < 0:
    print("象限三")
else:
    print("象限四")

